mapper.select:
/* 활동 카테고리별 다음날 에너지 변화량 평균 분석 */
SELECT category FROM (
    SELECT i.category, AVG(l_next.energy - l_curr.energy) as avg_boost
    FROM done_item i
    JOIN daily_log l_curr ON i.daily_log_id = l_curr.id
    JOIN daily_log l_next ON l_next.user_id = l_curr.user_id AND l_next.log_date = l_curr.log_date + 1
    WHERE l_curr.user_id = #{userId} AND l_curr.log_date BETWEEN #{startDate} AND #{endDate}
    GROUP BY i.category
    ORDER BY avg_boost DESC
) WHERE ROWNUM = 1
